//  useEvaluationData.ts
//  Hook — evaluationService மட்டும் call பண்ணும்
//  EvaluationConfig values மட்டும் import
// ═══════════════════════════════════════════════════════════════════════════

import { useState, useCallback, useRef } from "react";
import {
  EvalStatusId,
  EvalInterviewLevels,
  EvalUIConfig,
} from "../config/EvaluationConfig";
import {
  EvaluationService,
  evaluationService,
} from "../services/EvaluationService";
import {
  EvaluationCandidate,
  ScoreSheetResult,
  TooltipEntry,
} from "../services/IEvaluationService";

// ── Skeleton type (no spinner — shimmer rows instead) ─────────────────────
export type SkeletonRow = { __skeleton: true; id: number };
export type TableRow    = EvaluationCandidate | SkeletonRow;
export const isSkeleton = (r: TableRow): r is SkeletonRow => "__skeleton" in r;

const makeSkeletons = (): SkeletonRow[] =>
  Array.from(
    { length: EvalUIConfig.SkeletonRowCount },
    (_, i) => ({ __skeleton: true as const, id: i })
  );

// ─────────────────────────────────────────────────────────────────────────────

export function useEvaluationData(
  currentUserEmail: string,
  employeeList: any[]
) {
  const [rows, setRows]          = useState<TableRow[]>(makeSkeletons());
  const [tooltipData, setTooltip]= useState<TooltipEntry[] | null>(null);
  const panelDataRef             = useRef<any[]>([]);

  // ── MAIN FETCH — called once on tab mount ─────────────────────────────────
  const fetchData = useCallback(async () => {
    setRows(makeSkeletons()); // skeletons appear immediately

    // Step 1 — current user SP numeric ID
    const guid = await evaluationService.getCurrentUserGuid(currentUserEmail);
    if (!guid) { setRows([]); return; }

    // Step 2 — panels assigned to this user
    const panels = await evaluationService.getInterviewPanelsByUser(guid);
    panelDataRef.current = panels;
    if (!panels.length) { setRows([]); return; }

    const candidateIDs = [...new Set(panels.map((p: any) => p.CandidateID as number))];
    if (!candidateIDs.length) { setRows([]); return; }

    // Step 3 — combined candidate data (StatusId 16/20, ItemCreated "No")
    const rawCandidates = await evaluationService.getCombinedCandidates(
      candidateIDs,
      employeeList
    );
    if (!rawCandidates.length) { setRows([]); return; }

    // Step 4 — enrich each row with grade + level in parallel
    //          each resolved row replaces one skeleton progressively
    const settled: (EvaluationCandidate | null)[] = new Array(rawCandidates.length).fill(null);

    await Promise.all(
      rawCandidates.map(async (candidate: any, idx: number) => {
        const { grade, level, jobCodeID } = await evaluationService.getGradeAndLevel(
          candidate.RecruitmentID
        );
        const row = EvaluationService.buildRow(candidate, grade, level, jobCodeID);
        settled[idx] = row;

        // Replace one skeleton with this real row as soon as it resolves
        setRows((prev) => {
          const next = [...prev];
          const skIdx = next.findIndex(isSkeleton);
          if (skIdx !== -1) next[skIdx] = row;
          return next;
        });
      })
    );

    // Step 5 — Level-based final filter
    //          Same logic as InterviewPanelList.tsx finalValue filter (line 531–552)
    const finalRows = (settled.filter(Boolean) as EvaluationCandidate[]).filter((c) =>
      panels.some((item: any) => {
        if (c.id !== item.CandidateID) return false;
        if (
          c.statusId === EvalStatusId.InterviewScheduled &&
          item.InterviewLevel === EvalInterviewLevels.Level1
        ) return true;
        if (
          c.statusId === EvalStatusId.InterviewScheduledforLevel2 &&
          item.InterviewLevel === EvalInterviewLevels.Level2
        ) return true;
        return false;
      })
    );

    setRows(finalRows);
  }, [currentUserEmail, employeeList]);

  // ── ON-DEMAND: hover tooltip (user hovers status dot) ─────────────────────
  const fetchTooltip = useCallback(
    async (statusId: number | string, candidateID: number) => {
      // Determine level — same as InterviewPanelList handleHover (line 188–191)
      const level =
        statusId === EvalStatusId.InterviewScheduled
          ? EvalInterviewLevels.Level1
          : EvalInterviewLevels.Level2;
      const data = await evaluationService.getTooltipData(candidateID, level);
      setTooltip(data);
    },
    []
  );

  // ── ON-DEMAND: score sheet check (user clicks Evaluate icon) ──────────────
  const checkScoreSheet = useCallback(
    (
      candidateID: number,
      statusId: number | string
    ): Promise<ScoreSheetResult> =>
      evaluationService.checkScoreSheet(candidateID, statusId, currentUserEmail),
    [currentUserEmail]
  );

  return { rows, tooltipData, fetchData, fetchTooltip, checkScoreSheet };
}
